const canonicalRegions=['Amazonas','Áncash','Apurímac','Arequipa','Ayacucho','Cajamarca','Callao','Cusco','Huancavelica','Huánuco','Ica','Junín','La Libertad','Lambayeque','Lima','Loreto','Madre de Dios','Moquegua','Pasco','Piura','Puno','San Martín','Tacna','Tumbes','Ucayali'];
export const anaNormalize=value=>String(value??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/\s+/g,' ').trim().toLowerCase();
export function anaNumber(value){if(typeof value==='number')return Number.isFinite(value)?value:null;const text=String(value??'').trim().replace(/\s/g,'');if(!text||/^(s\.?d\.?|n\.?d\.?|-|--|sin.?dato)$/i.test(text))return null;if(!/^-?\d+(?:\.\d+)?$/.test(text))return null;const n=Number(text);return Number.isFinite(n)?n:null;}
const text=value=>String(value??'').replace(/\u00a0/g,' ').replace(/\s+/g,' ').trim();
function dateISO(value){const m=String(value).match(/^(\d{2})\/(\d{2})\/(\d{4})$/);if(!m)return null;const date=m[3]+'-'+m[2]+'-'+m[1];try{return new Date(date+'T00:00:00Z').toISOString().startsWith(date)?date:null;}catch{return null;}}
function metaDate(value){const q=value.match(/Fecha\s+en\s+consulta:\s*(\d{2}\/\d{2}\/\d{4})/i),p=value.match(/Fecha\s+impresi[oó]n:\s*(\d{2}\/\d{2}\/\d{4})\s+(\d{1,2}):(\d{2})\s*([ap])\.?\s*m\.?/i);let printedAt=null;if(p){let hour=Number(p[2]);const minute=Number(p[3]);if(hour>=1&&hour<=12&&minute<60){hour=hour%12+(p[4].toLowerCase()==='p'?12:0);const day=dateISO(p[1]);if(day)printedAt=day+'T'+String(hour).padStart(2,'0')+':'+p[3]+':00-05:00';}}return {queryDate:q?dateISO(q[1]):null,printedAt,printedAtPrecision:printedAt?'minute':null};}
export function requireAnaXls(bytes){const view=bytes instanceof Uint8Array?bytes:new Uint8Array(bytes);if(view.byteLength>5*1024*1024)throw Error('El XLS supera 5 MB. No se ha importado.');if(![208,207,17,224,161,177,26,225].every((n,i)=>view[i]===n))throw Error('Se requiere el XLS binario exportado por ANA. No se acepta una página HTML ni un archivo renombrado.');}
export function sourceHighlight(cell){const rgb=String(cell?.s?.fgColor?.rgb||'').toUpperCase().slice(-6);return {rgb:/^[A-F0-9]{6}$/.test(rgb)?rgb:null,level:rgb==='FFA500'?'naranja':rgb==='FF0000'?'rojo':!rgb||['FFFFFF','000000'].includes(rgb)?'sin_resalte':'otro_color'};}
export function parseAnaWorkbook(book,{filename='',fileHash='',importedAt=null}={}){
 const observations=[],duplicates=[],sheets=[];let reportTitle='',reportNumber=null,queryDate=null,printedAt=null,rawDateHeader='',sourceNote='';
 for(const sheetName of (book.SheetNames||[]).slice(0,8)){const sheet=book.Sheets[sheetName];if(!sheet||!sheet['!ref'])continue;const ref=(sheet['!fullref']||sheet['!ref']).split(':').pop();const rowCount=Number(ref?.match(/\d+$/)?.[0]);if(rowCount>10000)throw Error('El reporte supera 10000 filas; no se importará incompleto.');
  const cell=(r,c)=>sheet[String.fromCharCode(65+c)+(r+1)];const value=(r,c)=>{const direct=cell(r,c)?.v;if(direct!==undefined&&direct!==null&&direct!=='')return text(direct);const merge=(sheet['!merges']||[]).find(m=>m.s.r<=r&&m.e.r>=r&&m.s.c<=c&&m.e.c>=c);return merge?text(cell(merge.s.r,merge.s.c)?.v):'';};
  let cols=null;for(let r=0;r<Math.min(80,rowCount);r++){const values=Array.from({length:24},(_,c)=>anaNormalize(value(r,c)));if(values.includes('autoridad administrativa del agua')&&values.includes('nombre de la estacion')&&values.includes('rio')){cols={hydro:values.indexOf('region hidrografica'),aaa:values.indexOf('autoridad administrativa del agua'),ala:values.indexOf('administracion local del agua'),department:values.indexOf('departamento'),river:values.indexOf('rio'),station:values.indexOf('nombre de la estacion'),operator:values.indexOf('operador'),orange:values.indexOf('umbral naranja'),red:values.indexOf('umbral rojo'),time:values.indexOf('registro instantaneo'),trend:values.indexOf('tendencia')};const sub=Array.from({length:24},(_,c)=>anaNormalize(value(r+1,c)));cols.measurement=sub.findIndex(v=>/^valor/.test(v));cols.unit=sub.indexOf('unidad de medida');if(Object.values(cols).some(c=>c<0))cols=null;else break;}}
  if(!cols)continue;sheets.push(sheetName);
  for(let r=0;r<rowCount;r++){for(let c=0;c<24;c++){const raw=cell(r,c)?.v;if(typeof raw!=='string')continue;if(!reportTitle&&/REPORTE\s+N[°ºo.]?/i.test(raw)){reportTitle=text(raw);reportNumber=raw.match(/REPORTE\s+N[°ºo.]?\s*([\d-]+-ANA)/i)?.[1]||null;}if(/Fecha\s+en\s+consulta:/i.test(raw)){const metadata=metaDate(text(raw));if(queryDate&&metadata.queryDate&&queryDate!==metadata.queryDate)throw Error('El libro mezcla fechas de consulta; no se combinarán sin revisión.');queryDate=metadata.queryDate||queryDate;printedAt=metadata.printedAt||printedAt;rawDateHeader=text(raw);}if(/Datos primarios sin control de calidad/i.test(raw))sourceNote=text(raw);}
   const river=value(r,cols.river),station=value(r,cols.station),time=value(r,cols.time),rawValue=value(r,cols.measurement);const number=anaNumber(rawValue);if(!river||!station||anaNormalize(river)==='rio'||anaNormalize(station)==='nombre de la estacion'||(!/^\d{1,2}:\d{2}$/.test(time)&&number===null&&!/^s\.?d\.?$/i.test(rawValue)))continue;
   const parsedTime=/^(\d{1,2}):(\d{2})$/.exec(time);const recordTime=parsedTime&&Number(parsedTime[1])<24&&Number(parsedTime[2])<60?parsedTime[1].padStart(2,'0')+':'+parsedTime[2]:null;const rawDepartment=value(r,cols.department),department=canonicalRegions.find(x=>anaNormalize(x)===anaNormalize(rawDepartment))||rawDepartment;const orangeRaw=value(r,cols.orange),redRaw=value(r,cols.red),orange=anaNumber(orangeRaw),red=anaNumber(redRaw);const highlight=sourceHighlight(cell(r,cols.measurement));
   const row={hydrographicRegion:value(r,cols.hydro),aaa:value(r,cols.aaa),ala:value(r,cols.ala),department,departmentRaw:rawDepartment,river,station,operator:value(r,cols.operator),orangeThreshold:orange,redThreshold:red,orangeRaw,redRaw,recordTime,observedDate:null,value:number,valueRaw:rawValue,unit:value(r,cols.unit),trend:value(r,cols.trend),sourceHighlight:highlight.level,sourceColor:highlight.rgb,thresholdOrderReview:orange!==null&&red!==null&&red<orange,sourceRows:[{sheet:sheetName,row:r+1}]};observations.push(row);
  }
 }
 if(!sheets.length||!observations.length||!queryDate)throw Error('No se encontró un reporte ANA PRIOS compatible con encabezados, fecha de consulta y registros.');
 const unique=new Map();for(const row of observations){const {sourceRows,...data}=row;const key=JSON.stringify(data);if(unique.has(key)){unique.get(key).sourceRows.push(...sourceRows);duplicates.push(...sourceRows);}else unique.set(key,row);}const rows=[...unique.values()];const stationIdentity=r=>[r.department,r.aaa,r.ala,r.river,r.station,r.operator,r.unit].map(anaNormalize).join('|');const counts=new Map();rows.forEach(r=>counts.set(stationIdentity(r),(counts.get(stationIdentity(r))||0)+1));for(const r of rows)r.stationHasMultipleRecords=counts.get(stationIdentity(r))>1;
 return {schemaVersion:1,id:fileHash||('ana-'+queryDate+'-'+(printedAt||'')+'-'+rows.length),origin:'uploaded-xls',live:false,sourceUrl:null,portalUrl:'https://snirh.ana.gob.pe/onrh/Reportes.aspx?R=PRIOS',sourceFilename:filename,fileHash:fileHash||null,importedAt,reportNumber,reportTitle,queryDate,printedAt,printedAtPrecision:printedAt?'minute':null,rawDateHeader,sourceNote:sourceNote||'Datos primarios de la fuente; sujetos a revisión del operador.',notes:['La fecha de impresión es la generación de esta copia, no una actualización confirmada del portal.','El archivo solo indica la hora de cada registro, no su fecha individual. No se inventa un timestamp de observación.','Los colores se conservan del archivo; no se recalculan ni equivalen al semáforo editorial.','No sumar ni comparar globalmente valores expresados en unidades diferentes.'],counts:{rawRows:observations.length,records:rows.length,stations:counts.size,duplicatesRemoved:duplicates.length,departments:new Set(rows.map(r=>r.department)).size,orange:rows.filter(r=>r.sourceHighlight==='naranja').length,red:rows.filter(r=>r.sourceHighlight==='rojo').length,thresholdOrderReview:rows.filter(r=>r.thresholdOrderReview).length},rows};
}
export function latestAnaCopy(copies){return [...copies].sort((a,b)=>{const key=x=>Date.parse(x.printedAt||x.queryDate+'T00:00:00-05:00')||0;return key(b)-key(a);})[0]||null;}
